from pathlib import Path

from iris_dataset.image_metadata import inspect_image, is_supported_image_extension
from iris_dataset.models import AnomalyRecord, Eye, ImageRecord, ScanResult, SubjectInspection


EYES: tuple[Eye, Eye] = ("L", "R")


def scan_dataset(dataset_root: Path | str) -> ScanResult:
    root = Path(dataset_root)
    _require_dataset_root(root)

    records: list[ImageRecord] = []
    anomalies: list[AnomalyRecord] = []
    subject_eye_presence: dict[str, tuple[bool, bool]] = {}

    for subject_dir in _subject_directories(root):
        left_entries = _eye_entries(subject_dir, "L")
        right_entries = _eye_entries(subject_dir, "R")
        has_left = bool(left_entries)
        has_right = bool(right_entries)

        subject_eye_presence[subject_dir.name] = (has_left, has_right)
        if not has_left and not has_right:
            anomalies.append(AnomalyRecord(subject_dir.name, "missing_both_eyes"))

        for eye, entries in (("L", left_entries), ("R", right_entries)):
            for image_path in entries:
                result = inspect_image(root, image_path, subject_dir.name, eye)
                if isinstance(result, ImageRecord):
                    records.append(result)
                else:
                    anomalies.append(result)

    return ScanResult(root.resolve(), records, anomalies, subject_eye_presence)


def inspect_subject(dataset_root: Path | str, subject_id: str) -> SubjectInspection:
    root = Path(dataset_root)
    _require_dataset_root(root)

    subject_dir = root / subject_id
    if not subject_dir.is_dir():
        return SubjectInspection(subject_id, False, [], [])

    left_images = _supported_eye_image_names(subject_dir, "L")
    right_images = _supported_eye_image_names(subject_dir, "R")
    return SubjectInspection(subject_id, True, left_images, right_images)


def _require_dataset_root(dataset_root: Path) -> None:
    if not dataset_root.exists():
        raise FileNotFoundError(f"Dataset root does not exist: {dataset_root}")
    if not dataset_root.is_dir():
        raise NotADirectoryError(f"Dataset root is not a directory: {dataset_root}")


def _subject_directories(dataset_root: Path) -> list[Path]:
    return sorted(
        (entry for entry in dataset_root.iterdir() if entry.is_dir()),
        key=lambda path: path.name,
    )


def _eye_entries(subject_dir: Path, eye: Eye) -> list[Path]:
    eye_dir = subject_dir / eye
    if not eye_dir.is_dir():
        return []
    return sorted(
        (entry for entry in eye_dir.iterdir() if entry.is_file()),
        key=lambda path: path.name,
    )


def _supported_eye_image_names(subject_dir: Path, eye: Eye) -> list[str]:
    return [
        path.name
        for path in _eye_entries(subject_dir, eye)
        if is_supported_image_extension(path)
    ]

from pathlib import Path

from PIL import Image, UnidentifiedImageError

from iris_dataset.models import AnomalyRecord, Eye, ImageRecord


SUPPORTED_EXTENSIONS = {".jpg", ".jpeg", ".png"}


def is_supported_image_extension(path: Path) -> bool:
    return path.suffix.lower() in SUPPORTED_EXTENSIONS


def inspect_image(
    dataset_root: Path,
    image_path: Path,
    subject_id: str,
    eye: Eye,
) -> ImageRecord | AnomalyRecord:
    relative_path = _relative_image_path(dataset_root, image_path)

    if not is_supported_image_extension(image_path):
        return AnomalyRecord(subject_id, "invalid_format", eye, relative_path)

    try:
        with Image.open(image_path) as image:
            image.verify()
        with Image.open(image_path) as image:
            width, height = image.size
            image_format = image.format or image_path.suffix.lstrip(".").upper()
    except (UnidentifiedImageError, OSError, ValueError):
        return AnomalyRecord(subject_id, "corrupted_image", eye, relative_path)

    if width == 0 and height == 0:
        return AnomalyRecord(subject_id, "zero_dimension_image", eye, relative_path)

    return ImageRecord(
        subject_id=subject_id,
        eye=eye,
        image_path=relative_path,
        width=width,
        height=height,
        format=image_format,
        file_size=image_path.stat().st_size,
    )


def _relative_image_path(dataset_root: Path, image_path: Path) -> str:
    try:
        return image_path.relative_to(dataset_root).as_posix()
    except ValueError:
        return image_path.as_posix()

from iris_dataset.models import ScanResult, SubjectInspection
from iris_dataset.summary import build_scan_summary


def format_scan_summary(scan_result: ScanResult) -> str:
    summary = build_scan_summary(scan_result)

    return "\n".join(
        [
            f"Dataset root: {scan_result.dataset_root}",
            "",
            f"Subjects found: {summary.subjects_found}",
            f"- Both eyes present: {summary.both_eyes_present}",
            f"- Left eyes only: {summary.left_only}",
            f"- Right eyes only: {summary.right_only}",
            f"- Neither eye present: {summary.neither_eye_present}",
            "",
            "Total valid images:",
            f"- Left: {summary.left_image_count}",
            f"- Right: {summary.right_image_count}",
            "",
            f"Anomalies found: {summary.anomaly_count}",
        ]
    )


def format_subject_inspection(inspection: SubjectInspection) -> str:
    if not inspection.present:
        return f"Subject {inspection.subject_id} is not present."

    return "\n\n".join(
        [
            f"Subject: {inspection.subject_id}",
            _format_eye("Left eye", inspection.left_images),
            _format_eye("Right eye", inspection.right_images),
        ]
    )


def _format_eye(label: str, image_names: list[str]) -> str:
    if not image_names:
        return f"{label}:\nabsent"

    image_lines = "\n".join(f"- {name}" for name in image_names)
    return f"{label}:\nImages: {len(image_names)}\n{image_lines}"

